CREATE COLUMN TABLE "TEST_AP"."OEST" ("AbsEntry" INTEGER CS_INT NOT NULL , "SubID" INTEGER CS_INT NOT NULL , "SubType" NVARCHAR(50), "SuplyType" NVARCHAR(1) DEFAULT 'B', PRIMARY KEY ("AbsEntry")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OEST_SUB_TYPE" ON "TEST_AP"."OEST" ( "SubID" ASC );
CREATE INDEX "OEST_SUPLY_TYPE" ON "TEST_AP"."OEST" ( "SuplyType" ASC )